#include <bits/stdc++.h>
using namespace std;

vector<pair<long long, int>> factorize(long long n) {
    vector<pair<long long, int>> factors;

    for (long long p = 2; p <= n / p; ++p) {
        if (n % p != 0) continue;

        int cnt = 0;
        while (n % p == 0) {
            n /= p;
            ++cnt;
        }

        factors.push_back({p, cnt});
    }

    if (n > 1) {
        factors.push_back({n, 1});
    }

    return factors;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;

    vector<pair<long long, int>> factors = factorize(n);

    for (auto factor : factors) {
        cout << factor.first << '^' << factor.second << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

long long countDivisors(long long n) {
    long long answer = 1;

    for (long long p = 2; p <= n / p; ++p) {
        if (n % p != 0) continue;

        int cnt = 0;
        while (n % p == 0) {
            n /= p;
            ++cnt;
        }

        answer *= cnt + 1;
    }

    if (n > 1) {
        answer *= 2;
    }

    return answer;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;

    cout << countDivisors(n) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<int> buildPrimes(int limit) {
    vector<bool> isPrime(limit + 1, true);
    vector<int> primes;

    isPrime[0] = isPrime[1] = false;

    for (int i = 2; i <= limit; ++i) {
        if (!isPrime[i]) continue;

        primes.push_back(i);

        if (1LL * i * i <= limit) {
            for (int j = i * i; j <= limit; j += i) {
                isPrime[j] = false;
            }
        }
    }

    return primes;
}

vector<pair<long long, int>> factorize(long long n, const vector<int>& primes) {
    vector<pair<long long, int>> factors;

    for (int p : primes) {
        if (1LL * p * p > n) break;
        if (n % p != 0) continue;

        int cnt = 0;
        while (n % p == 0) {
            n /= p;
            ++cnt;
        }

        factors.push_back({p, cnt});
    }

    if (n > 1) {
        factors.push_back({n, 1});
    }

    return factors;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int limit;
    cin >> limit;

    vector<int> primes = buildPrimes(limit);

    long long n;
    cin >> n;

    vector<pair<long long, int>> factors = factorize(n, primes);

    for (auto factor : factors) {
        cout << factor.first << '^' << factor.second << '\n';
    }

    return 0;
}
